88	// Binary min-heap ordered by (expiresAt, insertion order). Expiry heaps are
89	// used three ways: one global heap drives reclamation, each resource gets one
90	// for lazy capacity accounting, and each quota node gets one for lazy quota
91	// accounting. Renewals push fresh nodes and retire the old ones, so reclaiming
92	// expired leases only walks entries that are actually due instead of scanning
93	// the whole table.
94	class ExpiryQueue {
95	  constructor() {
96	    this.nodes = [];
97	  }
98	
99	  get size() {
100	    return this.nodes.length;
101	  }
102	
103	  push(node) {
104	    const nodes = this.nodes;
105	    nodes.push(node);
106	    let i = nodes.length - 1;
107	    while (i > 0) {
108	      const parent = (i - 1) >> 1;
109	      if (expiresBefore(nodes[i], nodes[parent])) {
110	        [nodes[i], nodes[parent]] = [nodes[parent], nodes[i]];
111	        i = parent;
112	      } else {
113	        break;
114	      }
115	    }
116	  }
117	
118	  peek() {
119	    return this.nodes[0];
120	  }
121	
122	  pop() {
123	    const nodes = this.nodes;
124	    const top = nodes[0];
125	    const last = nodes.pop();
126	    if (nodes.length > 0) {
127	      nodes[0] = last;
128	      let i = 0;
129	      for (;;) {
130	        const left = i * 2 + 1;
131	        const right = left + 1;
132	        let next = i;
133	        if (left < nodes.length && expiresBefore(nodes[left], nodes[next])) {
134	          next = left;
135	        }
136	        if (right < nodes.length && expiresBefore(nodes[right], nodes[next])) {
137	          next = right;
138	        }
139	        if (next === i) {
140	          break;
141	        }
142	        [nodes[i], nodes[next]] = [nodes[next], nodes[i]];
143	        i = next;
144	      }
145	    }
146	    return top;
147	  }
148	}
149	
150	function expiresBefore(a, b) {
151	  if (a.expiresAt !== b.expiresAt) {
152	    return a.expiresAt < b.expiresAt;
153	  }
154	  return a.order < b.order;
155	}
