    const lease = {
      resource: item.resource,
      holder: event.holder,
      expiresAt: item.expiresAt,
      ttlMs: event.ttlMs,
      // Credentials issued before this process started are void: the
      // lease keeps occupying its resource, but its token cannot renew
      // or release it.
      legacy: true,
      heapSeq: 0,
      epoch: item.epoch,
      batch: null,
      chain: rs.chain,
